function heatmap(){const mode=S.modes[ui.heatMode];return pageHead('Property intelligence','See where work is happening, where data is missing, and what to collect next.',btn('3D campus','v5Expand','','secondary','box')+btn('Export spatial data','heatExport','','secondary','download')+btn('Explore environments','nav','gallery','primary','box'),'WEST CAMPUS / SPATIAL OPERATIONS')+
 `<div class="heat-command-bar">${heatModes()}<div class="heat-control-group"><button class="btn ghost small v4-flow-toggle" data-action="v4FlowToggle" aria-pressed="${ui.flowVisible}">${I('route','small')}Data flow ${ui.flowVisible?'on':'off'}</button><label><input type="checkbox" data-heat="sensors" ${ui.heatSensors?'checked':''}>Sensor positions</label><button class="btn ghost small" data-action="heatMethod">${I('info','small')}How to read this</button></div></div><div class="heat-layout"><section class="panel heat-main">${heatStage()}<div class="v4-map-legend-note"><span><i class="v4-small-key green"></i>Rings: synthetic capture sessions</span><span><i class="v4-small-key blue"></i>Trails: data-flow illustration, not tracked movement</span></div><div class="heat-timeline"><button class="icon-btn" data-action="heatPlay" aria-label="${ui.heatPlaying?'Pause':'Play'} simulated sample day">${I(ui.heatPlaying?'pause':'play','small')}</button><div class="timeline-control"><div><strong>Sample-day replay</strong><span data-sample-clock>${sampleClock()}</span></div><input id="heat-time" type="range" min="0" max="28" step="1" value="${ui.heatSlot}" data-heat="time" aria-label="Simulated time of day"><div class="time-ticks"><span>06:00</span><span>10:00</span><span>14:00</span><span>20:00</span></div></div><div class="opacity-control"><label for="heat-opacity">Overlay intensity <output id="heat-opacity-value">${ui.heatOpacity}%</output></label><input id="heat-opacity" type="range" min="0" max="100" value="${ui.heatOpacity}" data-heat="opacity"></div></div><div class="stage-description">${esc(mode.description)}</div></section>${heatPanel()}</div>${v4EvidenceStrip(ui.env,env(ui.env).captureSpace)}<section class="panel mt">${panelHead('All property zones','Select any environment. Hotspots and room locations are illustrative.',`<span class="badge neutral">20 selectable zones</span>`)}<div class="zone-register">${state.environments.map(e=>`<button class="zone-register-row ${ui.env===e.id?'selected':''}" data-action="heatSelect" data-id="${e.id}"><span class="step-icon">${I(e.icon,'small')}</span><span><strong>${esc(e.name)}</strong><small>${e.captureSpace} · ${e.spaces} training spaces</small></span><b>${heatValue(e)}</b></button>`).join('')}</div></section>`;}
function heatOverview(){return `<section class="panel overview-heat">${panelHead('The entire property. One operating picture.','Spatial view of the simulated campus',btn('Open property heatmap','nav','heatmap','small','arrow'))}<div class="overview-heat-grid"><div>${heatStage(true)}</div><div class="overview-heat-copy"><div class="eyebrow">PROPERTY INTELLIGENCE</div><h2>Turn a hotspot<br>into the next assignment.</h2><p>Click an environment to see its rooms, concept footage, data gaps and active work.</p><div class="heat-feature-line">${I('users','small')}Activity & collection coverage</div><div class="heat-feature-line">${I('chart','small')}Evaluation gaps & recovery plans</div><div class="heat-feature-line">${I('camera','small')}Room-level media & assignments</div>${btn('Explore the property','nav','heatmap','primary','arrow')}<small>Interactive simulation, not live sensor data.</small></div></div></section>`;}
