 $('#modal').querySelectorAll('video').forEach(v=>v.pause());
 const e=env(ui.roomEnv),room=ui.roomId,held=room===e.holdoutSpace,as=state.assignments.filter(a=>a.envId===e.id&&a.space===room),qs=state.datasets.filter(d=>as.some(a=>a.id===d.assignmentId)),clip=e.clip;
